-- test data
DELETE FROM membership;
INSERT INTO membership (id, democracy_id, profile_id, is_verified, is_verifying, timeout_end, timeout_count, timeout_total, timeout_history) SELECT (data->>'id')::uuid, (data->>'democracy_id')::uuid, (data->>'profile_id')::uuid, (data->>'is_verified')::boolean, (data->>'is_verifying')::boolean, (data->>'timeout_end')::timestamp, (data->>'timeout_count')::integer, (data->>'timeout_total')::integer, (data->>'timeout_history')::jsonb FROM tempmembership ON CONFLICT (id) DO UPDATE SET democracy_id = EXCLUDED.democracy_id, profile_id = EXCLUDED.profile_id, is_verified = EXCLUDED.is_verified, is_verifying = EXCLUDED.is_verifying, timeout_count = EXCLUDED.timeout_count, timeout_total = EXCLUDED.timeout_total, timeout_end = EXCLUDED.timeout_end, timeout_history = EXCLUDED.timeout_history;
